rust.credentials.rs:
pub fn authorization_decision(current_scheme: &str, _current_host: &str, current_port: &str, next_scheme: &str, _next_host: &str, next_port: &str, authorization: &str) -> &'static str {
    if authorization == "none" {
        return "absent";
    }
    if current_port == next_port {
        if current_scheme == "https" && next_scheme == "http" {
            return "strip";
        }
        return "keep";
    }
    "strip"
}

