rust.classification.rs:
pub fn config_kind(token: &str) -> &'static str {
    match token {
        "missing" => "missing",
        "null" => "null",
        "empty" => "missing",
        "one" | "two" | "three" => "list",
        _ => "invalid",
    }
}

rust.counts.rs:
pub fn item_count(token: &str, kind: &str) -> i64 {
    if kind != "list" { return 0; }
    match token { "one" => 1, "two" => 2, _ => 3 }
}

